const res = await tools.cdt.evaluate_script({
  pageId: 1,
  format: "function",
  function: `() => {
    var counts = {};
    var sels = ['.srp-results','.x-listing-root','.x-listing-grid-container','li','ul','.s-item','[data-viewport]','.x-listing-card-link','.srp-unsorted'];
    for (var i=0;i<sels.length;i++){
      counts[sels[i]] = document.querySelectorAll(sels[i]).length;
    }
    // Find a container that likely holds results: look for the grid/ul
    var ul = document.querySelector('ul.srp-results');
    var html = '';
    if (ul) html = ul.outerHTML.replace(/>\s+</g,'>').replace(/\n/g,' ').slice(0, 2000);
    // Also grab innerHTML of body first 3000 chars
    var bodyHtml = document.body.innerHTML.replace(/\n/g,' ').replace(/</g,'<');
    return JSON.stringify({counts: counts, srpResultsFound: !!ul, bodyStart: bodyHtml.slice(0,2500)});
  }`
});
console.log(res);

