const res = await tools.cdt.evaluate_script({
  pageId: 1,
  format: "function",
  function: `() => {
    var ul = document.querySelector('ul.srp-results');
    var cards = Array.prototype.slice.call(ul.querySelectorAll('li.s-card'));
    var out = [];
    for (var i=0;i<cards.length;i++){
      var card = cards[i];
      // skip pagination carousel cards that aren't listings
      var listingId = card.getAttribute('data-listingid') || '';
      var link = card.querySelector('a[href*="/itm/"]');
      if (!link || !listingId) continue;
      // Title: prefer an element with class title, else the first meaningful link text
      var title = '';
      var tEl = card.querySelector('.s-card__title, h3');
      if (tEl) title = tEl.textContent;
      var raw = card.innerText.replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();
      out.push({idx:i, listingId:listingId, url:'https://www.ebay.com/itm/'+listingId, title:(title||'').trim(), text:raw});
    }
    return JSON.stringify(out);
  }`
});
var arr = JSON.parse(res);
console.log("CARD COUNT:", arr.length);
