    var d = null;
    for (var i=0;i<details.length;i++){ if((details[i].innerText||'').replace(/\u00a0/g,' ').includes('Condition')){d=details[i];break;} }
    function getInput(){ return Array.prototype.slice.call(d.querySelectorAll('input[type=checkbox]')); }
    var toSelect = [2,3,4,5]; // Certified/Excellent/Very Good/Good - Refurbished
    for (var i=0;i<toSelect.length;i++){
