      setChecked.call(inp, true);
      inp.dispatchEvent(new Event('input', {bubbles:true}));
      inp.dispatchEvent(new Event('change', {bubbles:true}));
      // also click to trigger delegated listeners
      inp.click();
    }
    var now = getInput().map(function(x,idx){ return idx+':'+x.checked; });
    return JSON.stringify({state: now, url: location.href});
  }` });

