const raw = await tools.cdt.evaluate_script({ pageId: 1, format: "function", function: `() => {
    // Results count text
    var countText = '';
    var el = document.querySelector('.results'); if(!el){ el = document.body; }
    var m = el.innerHTML.match(/<title[^>]*>([\s\S]*?)<\/title>/);
    // gather active condition chips + sample card conditions
    var cards = Array.prototype.slice.call(document.querySelectorAll('ul.srp-results > li.s-card'));
    function parseCond(text){ 
      // eBay labels: 'Certified - Refurbished', 'Excellent - Refurbished', etc. Also 'Refurbished' substring
      return text.replace(/\u00a0/g,' ').trim(); 
    }
    var sample = [];
    for (var i=0;i<Math.min(12,cards.length);i++){
      var c = cards[i];
      var txt = (c.innerText||'').replace(/\u00a0/g,' ').replace(/\s+/g,' ');
      // find condition line
      var condMatch = txt.match(/(Certified - Refurbished|Excellent - Refurbished|Very Good - Refurbished|Good - Refurbished|Refurbished)/);
      var priceMatch = txt.match(/\$[\d,]+\.?\d*/);
      var title = (c.querySelector('.s-card__title, h3'));
      sample.push({cond: condMatch?condMatch[1]:'(none)', price: priceMatch?priceMatch[0]:'', t: (title?(title.innerText||'').replace(/\u00a0/g,' '):'').slice(0,90)});
    }
    // active filter chips near top
    var chips = Array.prototype.slice.call(document.querySelectorAll('.filter-chip, .spc__selected, [class*="Selected"], .srp-active-filters')).map(function(e){ return (e.innerText||'').replace(/\u00a0/g,' ').trim().slice(0,80); }).filter(function(x){return x;});
    return JSON.stringify({title: document.title.slice(0,120), sample: sample, chips: chips.slice(0,20)});
  }` });

