() => {
    function clean(s){ return (s||'').replace(/ /g,' ').replace(/\r/,' ').replace(/\n/g,' ').replace(/\t/g,' ').split('|').join(' ').trim(); }
    var cards = Array.prototype.slice.call(document.querySelectorAll('ul.srp-results > li.s-card'));
    var condLabels = ['Certified - Refurbished','Excellent - Refurbished','Very Good - Refurbished','Good - Refurbished'];
    function getCond(txt){ for (var i=0;i<condLabels.length;i++){ var p = txt.indexOf(condLabels[i]); if(p>=0) return condLabels[i]; } return ''; }
    // shipping: text after 'Free' or '+' up to newline
    function extract(shipRaw){ 
      shipRaw = shipRaw.replace(/\n/g,' ');
      if (shipRaw.length>120) shipRaw = shipRaw.slice(0,120);
      var s = clean(shipRaw);
      return s;
    }
    var out = [];
    for (var i=0;i<cards.length;i++){
      var c = cards[i];
      var listingId = c.getAttribute('data-listingid')||'';
      if(!listingId) continue;
      var link = c.querySelector('a[href*="/itm/"]');
      var titleTxt = '';
      var tEl = c.querySelector('.s-card__title, h3');
      if (tEl) titleTxt = tEl.innerText.replace(/\n/g,' ');
      var txt = clean(c.innerText);
      var cond = getCond(txt);
      // price: first '$....' 
      var pStart = txt.indexOf('$');
      var price = '';
      if (pStart>=0){ var seg = txt.slice(pStart, pStart+200).split('\n')[0]; price = clean(seg); }
      // shipping line: find 'Free' occurrences
      var shipTxt = '';
      var fIdx = txt.indexOf('Free');
      if (fIdx>=0){ shipTxt = clean(txt.slice(fIdx, fIdx+120)); }
      out.push({listingId: listingId, url:'https://www.ebay.com/itm/'+listingId, title: (titleTxt||'').slice(0,120), cond: cond, price: price, shipping: shipTxt});
    }
    return JSON.stringify(out);
  }

